    def format_args(self, **kwargs: Any) -> str:
        if self.config.autodoc_typehints in ('none', 'description'):
            kwargs.setdefault('show_annotation', False)
        elif self.config.autodoc_typehints == 'signature':
            kwargs.setdefault('show_annotation', True)

        try:
            self.env.app.emit('autodoc-before-process-signature', self.object, False)
            sig = inspect.signature(self.object, bound_method=True,
                                    follow_wrapped=not self.env.config.autodoc_inherit_docstrings)
            args = stringify_signature(sig, **kwargs)
        except (TypeError, ValueError):
            logger.warning(__('Failed to get a function signature for %s'), self.fullname,
                           type='autodoc')
            return None

        if self.args:
            # replace the whole signature with user-supplied one
            args = self.args
        if self.retann:
            # append the return annotation to the signature
            args += ' -> %s' % self.retann

        return args
