                    self.args = stringify_signature(sig, **kwargs)
                except (TypeError, ValueError) as exc:
                    logger.warning(__('Failed to get a function signature for %s: %s'),
                                   self.fullname, exc, type='autodoc')
                    return None

        return self.args
