                new = self.get_attr(self.object, '__new__', None)
                if new is not None:
                    self.args = self._get_signature(new)
            else:
                self.args = self._get_signature(self.object)

        if self.args is None:
            self.args = ''

        if self.retann is None:
            self.retann = self._get_return_annotation(self.object)

